-- SYNTHETIC DATA ONLY: NPDB CI restore drill, never sourced from production.
CREATE TABLE public.compounds (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  trivial_name text UNIQUE NOT NULL,
  molecular_formula text,
  published boolean NOT NULL DEFAULT false
);
CREATE TABLE public.specimens (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  compound_id bigint NOT NULL REFERENCES public.compounds(id) ON DELETE RESTRICT,
  organism text,
  voucher text
);
CREATE TABLE public.nmr_datasets (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  compound_id bigint NOT NULL REFERENCES public.compounds(id) ON DELETE RESTRICT,
  nucleus text NOT NULL CHECK (nucleus IN ('1H','13C')),
  solvent text NOT NULL,
  frequency_mhz integer,
  spectral_origin text NOT NULL CHECK(spectral_origin IN ('experimental','predicted')),
  source_doi text
);
CREATE TABLE public.nmr_peaks (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  dataset_id bigint NOT NULL REFERENCES public.nmr_datasets(id) ON DELETE CASCADE,
  delta_ppm numeric(8,4) NOT NULL,
  assignment text
);
CREATE TABLE public.spectra_files (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  dataset_id bigint NOT NULL REFERENCES public.nmr_datasets(id) ON DELETE RESTRICT,
  object_key text NOT NULL,
  content_sha256 text
);
CREATE TABLE public.bioactivity_records (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  compound_id bigint NOT NULL REFERENCES public.compounds(id) ON DELETE RESTRICT,
  assay text NOT NULL,
  value numeric(12,5),
  unit text
);
CREATE TABLE public.audit_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  actor text NOT NULL,
  action text NOT NULL,
  record_id bigint,
  event_time timestamptz NOT NULL DEFAULT now()
);

